// Fragments generated by tools/nb2mdx (in the course repo) from the exercise notebooks:
// blog/NN-name/code/X.ipynb -> src/content/exercises/X/{starter,solution,checkpoint}.mdx.
const modules = import.meta.glob("../../content/exercises/*/*.mdx", { eager: true }) as Record<string, any>;

export type Part = "starter" | "solution" | "checkpoint";

/** The generated module for one part of an exercise, or null if the notebook was not exported. */
export function fragment(notebook: string, part: Part) {
  const suffix = `/exercises/${notebook}/${part}.mdx`;
  const key = Object.keys(modules).find((k) => k.endsWith(suffix));
  return key ? modules[key] : null;
}
